import orders from './orders.json' with { type: 'json' };

const TOOL_NAME = 'order_status';

const inputSchema = {
  type: 'object',
  properties: {
    order_id: { type: 'string' },
    include_history: { type: 'boolean', default: false },
  },
  required: ['order_id'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description: 'Get the current status of an order, with optional chronological history.',
      inputSchema,
    },
  ];
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const known = new Set(Object.keys(inputSchema.properties));
  const extra = Object.keys(args).filter((k) => !known.has(k));
  if (extra.length > 0) {
    throw new Error(`Invalid argument(s): ${extra.join(', ')}`);
  }

  const { order_id, include_history = false } = args;

  if (typeof order_id !== 'string' || order_id.length === 0) {
    throw new Error('Missing or invalid required argument: order_id');
  }

  if (typeof include_history !== 'boolean') {
    throw new Error('Invalid argument: include_history must be a boolean');
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Unknown order: ${order_id}`);
  }

  const lines = [`status: ${order.status}`];
  if (include_history) {
    lines.push(`history: ${order.history.join(', ')}`);
  }

  return textResult(lines.join('\n'));
}

